// Presentation choreography only. These drives are never generated by /api/turn.
export const WARNING_AT = 3;
export const CLEAR_AT = 9.5;
export const FOUND_AT = 4.5;
export const MOCK_TARGET = { x: 1.58, y: 1.52, label: '모의 폭발물' };

export function choreography(kind, time) {
  const wave = Math.sin(time * 2.8);
  if (kind === 'search') return time < FOUND_AT ? {
    expression: 'thinking', label: '훈련 구역 탐색 중', accent: '#85d9eb',
    drive: { linear: .14, angular: .22 },
    joints: { headYaw: 25 * Math.sin(time * 3), headPitch: -6, waistYaw: 8 * Math.sin(time * 1.5) },
    marker: { ...MOCK_TARGET, detected: false },
  } : {
    expression: 'alert', label: time < 7 ? '발견 · 정지 / 보고 중' : '관제 수신 확인 · 정지 유지',
    accent: '#ffa497', marker: { ...MOCK_TARGET, detected: true },
  };
  if (kind === 'alert') {
    if (time < WARNING_AT) return {
      expression: 'listening', label: '직접 명령 · 전진', accent: '#b6efb3',
      joints: { headYaw: 0, headPitch: -3, waistYaw: 0 },
    };
    if (time < CLEAR_AT) return {
      expression: 'alert', label: '경고 · 정지 유지', accent: '#ffa497',
    };
    return { expression: 'idle', label: '해제 · 새 명령 대기', accent: '#b6efb3' };
  }

  const drive = time < 2.8 ? {
    query: { linear: .12, angular: .48 },
    report: { linear: .14, angular: -.32 },
    orders: { linear: .13, angular: .65 * Math.sin(time * 2.2) },
  }[kind] : { linear: 0, angular: 0 };
  const base = { drive, accent: kind === 'report' ? '#85d9eb' : '#b6efb3' };
  if (time < 2.8) return { ...base, expression: 'listening', label: '듣는 중 · 이동 연출',
    joints: { headYaw: 12 * wave, headPitch: -8, waistYaw: 5 * Math.sin(time * 1.8) } };
  if (time < 3.6) return { ...base, expression: 'thinking', label: '원문 확인 중',
    joints: { headYaw: 18, headPitch: 8, waistYaw: -8 } };
  if (kind === 'query') return { ...base, expression: 'happy', label: '근거 확인 · 끄덕임',
    joints: { headYaw: 5 * Math.sin(time * 1.2), headPitch: 12 * Math.sin((time - 3.6) * 4), waistYaw: 0 } };
  if (kind === 'report' && time < 7) return { ...base, expression: 'thinking', label: '보고 항목 정리 중',
    joints: { headYaw: 16 * Math.sin((time - 3.6) * 2), headPitch: 5, waistYaw: -5 } };
  if (kind === 'report') return { ...base, expression: 'happy', label: '저장 확인 · 끄덕임',
    joints: { headYaw: 0, headPitch: 13 * Math.sin((time - 7) * 4), waistYaw: 6 * Math.sin((time - 7) * 2) } };
  if (time < 5) return { ...base, expression: 'thinking', label: '담당·기한 대조 중',
    joints: { headYaw: 20 * Math.sin((time - 3.6) * 3), headPitch: 3, waistYaw: 0 } };
  return { ...base, expression: 'uncertain', label: '기한 미확인 · 재확인 대기', accent: '#f4cb81',
    joints: { headYaw: -16 + 4 * Math.sin(time * 1.8), headPitch: 11, waistYaw: 9 } };
}
